params.search:
var name := dir.get_next()
while name != "":
	var full := dir_path + "/" + String(name)
	if dir.current_is_dir() and not String(name).begins_with("."):
		_scan_music_dir(full)
	else:
		var low := String(name).to_lower()
		if low.ends_with(".wav") or low.ends_with(".ogg"):
			playlist.append(full)
	name = dir.get_next()

